    /* --- Hallo (general application) --- */
    'app.heading':     'Hello.',
    'app.lead':        'I build brand experiences that work beyond the day of the event.',
    'app.p1':          'I am Shayna Jucker, 28, based in Pf&auml;ffikon ZH. At TIT-PIT I am responsible for Migros brand experiences at more than ten Swiss music festivals &ndash; from the first briefing to the last truck leaving the ground.',
    'app.p2':          'I started somewhere else: five years as an architectural drafter, then a degree in Multimedia Production with a specialisation in Live Communication. That combination explains how I work. I read a stand plan like a drafter, think the brand like a strategist and stand on site at six in the morning on build day.',
    'app.p3':          'This page is not an application for one specific job. It shows what people hire me for &ndash; and how I work when things get tight.',
    'app.roles-heading':'roles',
    'app.roles-sub':   'What people hire me for',
