    'app.r3-proof':    'In project ownership roles continuously since 2020 &ndash; first in architecture, today in live marketing.',
    'app.r3-role':     'Interface between client, creation, production and crew. Decide, prioritise, follow up.',
    'app.r3-a1':       'Full client ownership from briefing to final report',
    'app.r3-a2':       'Budget responsibility and quoting',
