    'app.how-heading': 'principles',
    'app.how-sub':     'How I work',
    'app.h1-label':    'Understand first, promise second',
    'app.h1-text':     'I would rather tell a client in the briefing that something will not work than on build day. It takes courage once and saves money three times.',
    'app.h2-label':    'The event is not the goal',
    'app.h2-text':     'An appearance only works for me when it lives on beyond the moment. That is why I plan content in from the start, not as an afterthought.',
